import type { Settings } from '@/platform/settings/types'

export interface PromptTarget {
  element?: HTMLElement
  finish?: () => void
  title: string
  read: () => string
  write: (value: string) => void
}

export interface DeviceHost {
  registerBack: (
    dismiss: () => boolean,
    priority: number,
    name?: string
  ) => () => void
}

export interface DeviceServices {
  readonly branch: 'cloud' | 'hosted'
  start(host: DeviceHost): Promise<void>
  resume(): void
  stop(): void
  preferences: {
    read(seed: () => Promise<Settings>): Promise<Settings>
    write(values: Partial<Settings>, seed: () => Promise<Settings>): Promise<Response>
  }
  prompt: {
    open(target: PromptTarget): boolean
    close(): boolean
    sync(read: PromptTarget['read']): void
    syncElement(element: HTMLElement): void
    release(read: PromptTarget['read']): void
  }
  createSettings(): { element: HTMLElement; remove(): void }
  layout?: { read(): string | null; write(value: string): void }
  trackPrompt(id: string): void
}

declare global {
  interface Window {
    __comfierDevice?: DeviceServices
  }
}

export async function prepareDevice() {
  if (!window.ComfierApp) return
  const path = '/__comfier_device__/parent.js'
  await import(/* @vite-ignore */ path)
  if (!window.__comfierDevice) throw new Error('Device services did not initialize')
}
